// ec-canvas.js
Component({
    properties: {
      ec: {
        type: Object
      }
    },
    data: {},
    ready() {
      if (!this.data.ec) {
        console.error('组件需绑定 ec 变量，例：<ec-canvas ec="{{ ec }}"></ec-canvas>');
        return;
      }
      if (!this.data.ec.lazyLoad) {
        this.init();
      }
    },
    methods: {
      init(callback) {
        const version = wx.getSystemInfoSync().SDKVersion;
        const v = version.split('.').map(x => parseInt(x));
        if (v[0] * 100 + v[1] * 10 + v[2] < 290) {
          console.error('基础库版本过低，需升级至 2.9.0 以上');
          return;
        }
        const canvas = this.createSelectorQuery().select('#ec-canvas');
        canvas.fields({ node: true, size: true }).exec(res => {
          const canvasNode = res[0].node;
          const ctx = canvasNode.getContext('2d');
          const dpr = wx.getSystemInfoSync().pixelRatio;
          canvasNode.width = res[0].width * dpr;
          canvasNode.height = res[0].height * dpr;
          const chart = require('./echarts.min.js').init(canvasNode);
          this.setData({ chart });
          callback && callback(canvasNode, res[0].width, res[0].height, dpr);
        });
      }
    }
  });